content.text:
{
 "包": "M02",
 "答案": [
  {
   "题": "题02",
   "最符合": "C",
   "排序": [
    "C",
    "D",
    "B",
    "A"
   ],
   "理由": {
    "A": "天梁坐命断个子不高、粗壮圆脸，与瘦瘦高高相反；断娶美妻、太太娶得很好，与婚姻极差、生离死别矛盾；命宫是官不是商，也与到私人企业从商不符，整体最不相符。",
    "B": "紫微天相坐命断脸宽厚重、一定掌权做主管、财官双美、身在官禄一定当官，与职位高但无实权、辅佐型、到私人企业从商矛盾；合伙变仇人与合伙大有利矛盾；只有专业技术、善理财、无子、父母离散几点相符。",
    "C": "天相坐命瘦高、只能做佐才参谋而不能统御领导，正合职位高无实权的辅佐型；身在财帛主私人企业、自己做事业、善理财家财万贯，合钱财事业最好；迁移到外地逢贵人、靠专业专长赚钱；夫妻宫老婆会赌光家财、多次结婚、太阴化忌婆媳不和；子女化忌无子；仆役合伙大吉；父母有凶离散，几乎全部对应，仅眼睛之说陈述未提。",
    "D": "天相坐命瘦高斯文、文采风流读书很棒、想不开、命宫化忌劫杀意外，身在夫妻被婚姻影响很大，这些与文采好、自杀倾向、29岁横祸、太太影响最大相符；但断合伙变仇人、破财、一辈子领薪水、肾脏不好、脸头很大五官挤在一起，与合伙大有利、善聚财从商、肺胃脾毛病、瘦高相貌相矛盾。"
   }
  }
 ]
}

{
 "包": "M20",
 "答案": [
  {
   "题": "题20",
   "最符合": "B",
   "排序": [
    "B",
    "A",
    "D",
    "C"
   ],
   "理由": {
    "A": "破军坐命主武官、科甲读书好，与「若为男能出将入相」及公家考试顺利部分相符；但命属偏房、婆媳不和、田宅破祖业、不靠祖业起家，与配偶温和厚道、豪门有祖业可分明显矛盾。",
    "B": "紫微贪狼坐命，杀星武将「给男人比较好」正合「如果是男人了不得」，主官带、武官最利、科甲考试好、命中有权可为领导，对应将军警察可做局长、紫衣金带；夫妻宫天府温和厚道合「老婆好得不得了」，命宫与田宅宫皆断生有祖业、祖业很大，合豪门有祖业可分，几乎无矛盾。",
    "D": "天梁太阳坐命文武双全、武官带、天魁发科甲，与公家考试顺利、武职略有呼应；但官禄宫断命里没有官带不会当官、不靠祖业起家、太太聒噪凶悍，与升到局长尊贵地位、配偶温和、分得祖业不符。",
    "C": "天相坐命厚道温和、迁移宫武官大利有部分呼应；但明断命里没有官带不会当官、身在财帛走私企或自做生意、老婆会把家财赌光、不靠祖业起家，与出将入相、公家升迁、配偶温和厚道、有祖业可分多处矛盾。"
   }
  }
 ]
}

{
 "包": "M15",
 "答案": [
  {
   "题": "题15",
   "最符合": "C",
   "排序": [
    "C",
    "B",
    "A",
    "D"
   ],
   "理由": {
    "A": "命宫「招美妻、娶的太太都很漂亮」与陈述18相符，夫妻宫官非也可勉强对应官司；但天梁坐命「英俊潇洒」与「本人不见得好看」矛盾，太阳火爆、个性很强、武官文官路线与「性情柔和、胆小如鼠、靠才艺」不合，且全盘没有多次结婚、克妻的迹象。",
    "B": "破军坐命走文笔才华、作家画家专业，命属偏房、太阴化忌「婚姻一定完蛋、太太二婚」可对应多婚克妻，不重利重感觉也近似才子气；但个性刚强孤僻、谁的话都不听与「性情柔和、内心胆小」不符，官司是非只在子女宫而非本人，太阳落陷伤眼也无陈述对应。",
    "C": "天相坐命斯文温和、厚道谦和、才艺博学、文采风流，正合「性情柔和、画画弹琴作曲讨女孩子欢心」；命宫化忌带官司纠纷、破财、事与愿违、停滞、早年辛苦而后转好，正合「事倍功半、官司纠纷、之后才艺显现一直顺到老」；身宫在夫妻「后天被婚姻影响很大」、婚姻不好但凶处藏吉，合「多次结婚却在婚姻上成好命」；脸头大五官挤在一起合「本人不好看」。小不符处是夫妻宫「主妻长」与晚年娶小十几二十岁的太太相反。",
    "D": "紫微贪狼坐命魁梧厚重、不苟言笑、刚强狠犟、天生领导者有生杀之权、祖业大命带禄，与「外刚内柔、胆小如鼠、性情柔和、靠才艺」几乎全部相反，夫妻宫天府厚道善理财也无多婚克妻之象，仅「文采风流」一句沾边，最不符合。"
   }
  }
 ]
}

{
 "包": "M12",
 "答案": [
  {
   "题": "题12",
   "最符合": "D",
   "排序": [
    "D",
    "C",
    "B",
    "A"
   ],
   "理由": {
    "A": "命宫男人的命、刚强、做生意当老板、官司横祸、福德多婚与陈述中劳碌、经商、是非、再婚相合，但父母宫断旺父母、孝顺家里，与三岁父母离散、早失父亲相悖，且断先生不好与「先生人很好」不符。",
    "B": "命宫刚强、拗、男人的命、桃花→婚事不成，夫妻宫配偶善良温和厚道，父母宫凶星是非、注意父母安全，与早年失父、20岁婚事不成、先生人好相合；但路线偏军人、宜为人手下，缺少偏房、经商当老板的判断。",
    "C": "命宫刚躁固执、奔波加倍辛苦、不靠男人自己赚钱、一个人持家、夫妻宫离婚二婚、少一只眼睛与陈述中劳碌、独立、婚姻破裂、眼睛异常部分相合；但断先生比她差与「先生人很好」矛盾，断不做生意也与34岁后经商不合。",
    "D": "命宫直接断偏→做偏房、正财→帮人做事领薪水、巨贾、白天晚上都忙加倍辛苦、拗固执自以为有理、心眼多→害到自己、受母亲影响、六亲不靠、迁移生意发展到外地，父母宫武官带桃花酒色，与庶出、偏房、先打工后经商、刚拗死不认错、父母离散等陈述高度相符；仅子女宫儿子远离与「儿子在身边」略有出入。"
   }
  }
 ]
}

{
 "包": "M10",
 "答案": [
  {
   "题": "题10",
   "最符合": "A",
   "排序": [
    "A",
    "B",
    "C",
    "D"
   ],
   "理由": {
    "A": "命宫性刚、主见强、领导力强、化科读书考试好、科权禄会齐可做事业有财；官禄宫明言靠专科技术专长、自己一人开事务所、参加考试一考就上；夫妻宫借对宫同样是专业技术专长者（丈夫同行）；子女宫无子嗣；仆役宫合伙事与愿违、与朋友变成仇人、必败；父母宫孤星独守主一辈子孤单可应早年失父。几乎逐条相符，仅迁移宫未明言外地凶、福德多婚略有出入。",
    "B": "个性拗犟很刚、化忌冲命火大了就不干了、身宫财帛走私人企业或自己做事业、无子嗣，这些相符；但只能做佐才不能统御、父母从商且有牢狱、配偶为武官带而非同行专业人士、仆役为公务人员而非反目成仇，与陈述多处不合。",
    "C": "个性刚强固执、夫妻宫化科走自由业专科技术（丈夫同行）、子女宫无子女相符；但命宫文官带领固定薪水不走武官不做生意，与自己出来做事业矛盾，身宫在迁移势必去外地、一去无回，与外地凶本地吉相反，另有少一只眼睛、做偏房等陈述未提。",
    "D": "化忌冲命火大不干出来、身宫在官禄会当官两点相符；但子女宫主二子与无子女直接矛盾，天马读书到外地与本地吉外地凶相反，夫妻宫先生比她差、主二婚、姻缘由父母挑选，与丈夫同行专业、早婚不合，仆役认识有钱人也无反目之象，最不相符。"
   }
  }
 ]
}

{
 "包": "M07",
 "答案": [
  {
   "题": "题07",
   "最符合": "B",
   "排序": [
    "B",
    "A",
    "C",
    "D"
   ],
   "理由": {
    "A": "天相坐命厚道、专科技术专长、帮人领薪水、读书好、身宫在夫妻、子女宫一子做生意有财、命宫事与愿违孤军等都相符，但父母宫未见离散刑克，且命宫兼有心胸恶毒之说，与克父母离散、正派为人的核心陈述略有出入。",
   "B": "天梁坐命读书考试好、一定做主管、有专科专长、身宫在夫妻后天受婚姻影响大、夫妻宫巨门吵架不断正合太太聒噪凶悍、子女宫贪狼化禄一子做生意有财、父母宫七杀火铃离散父母、命受化忌对冲与迁移劫杀合命硬该夭、田宅有财星合中年产业增加，矛盾最少。",
   "C": "父母宫离散父母、子女有一男孩、化忌对冲命宫等相符，但命宫武曲必招美妻、太太娶得很好、命带禄生来有钱、身宫在福德，与婚姻最累、靠专业领薪水、事与愿违等陈述明显矛盾。",
   "D": "天相厚道、父母宫离散父母相符，但明言只能做佐才不见得能统御领导、身宫在财帛影响最大不在夫妻、自己做生意、子女宫化忌无子子女凶、多次结婚，与掌权做主管、婚姻最累、领固定薪水、有一儿子做老板等核心陈述多处矛盾。"
   }
  }
 ]
}

{
 "包": "M18",
 "答案": [
  {
   "题": "题18",
   "最符合": "D",
   "排序": [
    "D",
    "A",
    "B",
    "C"
   ],
   "理由": {
    "A": "命宫有佐才、正财，路线有当助理秘书、帮人做事领薪水、私人企业做事，与陈述1相符；但同时又断武官星、君王、官带、当将军、当老板、自己做事业，路线矛盾分散，且本人健康意外几乎未提，配偶只断刚强耐劳而非能力强，相符度次于D。",
   "B": "命宫有佐才、当助理秘书，并有婆媳不和，表面与陈述1、7相符；但通篇是女命口吻（做偏房、多婚、不做家庭主妇、做职业妇女、中年先生有问题），像是配偶一方的命盘，而非这位中风丈夫本人的盘，故不取。",
   "C": "命宫断武官星、文武双全、当官、不做生意、成格，与领薪水当助手的路线不符；夫妻宫断太太凶悍聒噪、很累，与太太能力强在旁照顾也不相称，本人健康问题亦无，最不相符。",
   "D": "命宫佐才→当助理秘书、正财→帮人做事领薪水、孤单→对老板有利，官禄有私人企业做事、不会当官，完全对应陈述1；夫妻宫为身宫，配偶主见强、领导力强、大财星、大吉，后天受婚姻影响大，对应太太能力强并照顾他；命宫又断健康最不好、伤身、意外灾、横祸、灾应本人，对应53岁中风致瘫；唯独未明写婆媳不和，整体最符合。"
   }
  }
 ]
}

{
 "包": "M10",
 "答案": [
  {
   "题": "题10",
   "最符合": "A",
   "排序": [
    "A",
    "B",
    "D",
    "C"
   ],
   "理由": {
    "A": "命宫刚强、个性强、专业技术专长、能做事业、做生意当老板，官禄一考就上、金榜题名，夫妻宫专业技术专长、金榜题名（丈夫同行且有专长），子女宫无子，仆役宫朋友变仇人、合伙必败，迁移刃开血光（外地凶），兄弟宫代表父亲且凶灾横祸可对应早年丧父，大怒之下犯大错对应火大不干；仅父母宫旺父母略有出入，整体最相符。",
    "B": "专业技术专长、考试很棒、火大不干、子女宫无子、父母宫提醒父母健康安全与陈述相合；但命宫宜为人手下、去给国家管与不屈居人下矛盾，婚事不成与早婚矛盾，夫妻宫温和善良无专长，仆役宫无朋友变仇人之象，相符度次之。",
    "D": "不靠男人、自己赚钱、火大不干、父母宫早婚与陈述相合；但动而出外地读书与外地凶矛盾，子女一子二子与无子矛盾，仆役合伙吉与朋友变仇人矛盾，夫妻宫先生比她差、离婚、宜嫁二婚夫与丈夫同行有专长不符，矛盾较多。",
    "C": "夫妻宫专业技术专长、金榜题名、婚姻好与丈夫同行有专长相合，刚强固执也近似；但身宫在迁移主到外地发展一去不回与外地凶矛盾，正财帮人做事领薪水、公家单位与自己出来做矛盾，子女宫儿子远离与无子矛盾，做偏房、聚少散多与婚姻陈述不符，最不相符。"
   }
  }
 ]
}

{
 "包": "M24",
 "答案": [
  {
   "题": "题24",
   "最符合": "A",
   "排序": [
    "A",
    "D",
    "C",
    "B"
   ],
   "理由": {
    "A": "命宫个性强、刚强、孤僻、孤单、瘦（脸无肉），身宫在夫妻且「后天受婚姻影响大」、夫妻宫专业技术专长（先生靠技术吃饭）、财帛官禄私人企业做事且当官不容易、子女一子、福德多婚、父母宫官带文官带当官（父母是官），与陈述大量相符；唯命宫「离乡走天下」与「不可能到外地发展」相抵。",
   "D": "夫妻宫二婚、离婚、忌由先生而来，子女一子男性，财帛私人企业、官禄当官不容易，父母是武官，福德多婚，与婚姻六亲相符；但命宫个子矮、五短、壮与皮包骨的瘦脸矛盾，命宫武官星走军警路线也与不当官不合。",
   "C": "夫妻宫二婚、专业技术专长，父母当官相符；但命宫长绒肥胖、个子矮、皮肤黑与瘦脸相反，命宫正财文官带、公家单位、当公务员与不会当官、做私人企业相抵，又断婚姻好、善于理财家财万贯，与离婚孤独不符。",
   "B": "命宫个性强、孤单、好的看不上她略合，父母是武官、财帛私人企业亦可对上；但长相头脸大、五官挤在一起与瘦脸不符，成败停滞、比较惨、灾应本人与晚年运好事业佳相反，夫妻宫只断吵架大打出手而无二婚离婚之象，整体最不相符。"
   }
  }
 ]
}

{
 "包": "M14",
 "答案": [
  {
   "题": "题14",
   "最符合": "C",
   "排序": [
    "C",
    "A",
    "D",
    "B"
   ],
   "理由": {
    "A": "命宫可做生意当老板、子女宫「宜嫁二婚夫、嫁同龄初婚者凶」与她专喜欢已婚男人相符，仆役「朋友变仇人」亦合不会看人替人作保；但兄弟宫为凶星、是非口舌、开刀，与「兄弟姐妹得力、宜合伙」直接矛盾，命宫也偏官带武官。",
    "B": "夫妻宫二婚离婚、福德婚姻不好与其婚事难成相符，父母宫武官星亦合；但兄弟宫兄弟不和、合伙破财与「兄弟得力宜合伙」严重相反，命宫「男人的命」、桃花刚烈也与偏文、少接近男人不符。",
    "C": "命宫偏房格、婚姻难有着落、孤单、红光满面（印堂发红）、容易被人影响（不会看人）、小人多；仆役宫「与合伙人同居、没有名分的先生」合其专恋已婚男人；兄弟宫大吉兄弟得利、父母宫武官军人、官禄掌权做主管、事业做得大、迁移作家画家（偏文）均相符；仅夫妻宫「婚姻好」一项不合。",
    "D": "命宫文、文武双全（偏文）、兄弟宫君王贵人兄弟得力、父母宫武官星、官禄做主管掌权与陈述相符；但官禄主当公务员当官与「不会当官、宜外地经商」相反，夫妻宫会结婚婚姻好、命宫旺夫也与她婚事始终不成不符。"
   }
  }
 ]
}

{
 "包": "M27",
